/// <reference path="../pb_data/types.d.ts" />

// Expands the Notifications workspace backend.
//
// ghost_notifications already exists (created in 1791368216) with a small set
// of types generated by hooks. This migration:
//   1. Widens the `type` select to cover every Notifications category —
//      Contributions, Reviews, Projects, Table Talks, Collaboration,
//      Mentions, Moderation, Account/Security, and System notices — so hooks
//      can emit the richer event set the workspace surfaces.
//   2. Adds an `archived` bool so a Ghost can archive notices they have dealt
//      with (without deleting them), separate from the `read` flag.
//   3. Adds a `category` select so filtering is server-side and stable even
//      if a type is later renamed. Backfilled for existing rows from `type`.
//   4. Creates `ghost_notification_preferences` — owner-scoped email-channel
//      preferences. Security-critical notices are never fully suppressible:
//      the `email_security_events` flag is present for transparency but the
//      hook that sends mail always sends security notices regardless of it.
//
// Additive only — no existing rule is changed.

const TYPE_VALUES = [
  // System / onboarding
  'welcome',
  'system_notice',
  // Contributions
  'work_published',
  'work_rejected',
  'work_revision_requested',
  'work_archived',
  // Reviews
  'review_received',
  'review_feedback',
  // Projects
  'project_invitation',
  'project_task_assigned',
  'project_update',
  'participation_received',
  // Table Talks
  'table_talk_role_assigned',
  'table_talk_scheduled',
  'table_talk_decision',
  // Collaboration
  'collaboration_request_received',
  'collaboration_request_updated',
  // Mentions
  'mention',
  // Moderation
  'moderation_notice',
  'report_received',
  // Account / Security
  'security_notice',
  'application_accepted',
  'application_declined',
];

const CATEGORY_VALUES = [
  'system',
  'contributions',
  'reviews',
  'projects',
  'table_talks',
  'collaboration',
  'mentions',
  'moderation',
  'security',
];

// type → category mapping used to backfill the new `category` field.
const TYPE_TO_CATEGORY = {
  welcome: 'system',
  system_notice: 'system',
  work_published: 'contributions',
  work_rejected: 'contributions',
  work_revision_requested: 'contributions',
  work_archived: 'contributions',
  review_received: 'reviews',
  review_feedback: 'reviews',
  project_invitation: 'projects',
  project_task_assigned: 'projects',
  project_update: 'projects',
  participation_received: 'projects',
  table_talk_role_assigned: 'table_talks',
  table_talk_scheduled: 'table_talks',
  table_talk_decision: 'table_talks',
  collaboration_request_received: 'collaboration',
  collaboration_request_updated: 'collaboration',
  mention: 'mentions',
  moderation_notice: 'moderation',
  report_received: 'moderation',
  security_notice: 'security',
  application_accepted: 'security',
  application_declined: 'security',
};

migrate((app) => {
  const users = app.findCollectionByNameOrId('users');

  // --- 1. Expand ghost_notifications ---
  const notifications = app.findCollectionByNameOrId('ghost_notifications');

  const typeField = notifications.fields.getByName('type');
  if (typeField) {
    typeField.values = TYPE_VALUES;
  }

  // category select (new)
  if (!notifications.fields.getByName('category')) {
    notifications.fields.add(
      new SelectField({
        name: 'category',
        required: true,
        maxSelect: 1,
        values: CATEGORY_VALUES,
      }),
    );
  }

  // archived bool (new)
  if (!notifications.fields.getByName('archived')) {
    notifications.fields.add(new BoolField({ name: 'archived' }));
  }

  app.save(notifications);

  // Backfill category on existing rows (required field; new bool `archived`
  // defaults to false automatically).
  const existing = app.findAllRecords('ghost_notifications');
  for (const rec of existing) {
    if (!rec.getString('category')) {
      const t = rec.getString('type');
      rec.set('category', TYPE_TO_CATEGORY[t] || 'system');
      app.save(rec);
    }
  }

  // --- 2. Notification preferences ---
  let preferences;
  try {
    preferences = app.findCollectionByNameOrId('ghost_notification_preferences');
  } catch (_) {
    preferences = new Collection({
      name: 'ghost_notification_preferences',
      type: 'base',
      // Owner-only. One row per member (enforced by unique index).
      listRule: "@request.auth.id != '' && owner = @request.auth.id",
      viewRule: "@request.auth.id != '' && owner = @request.auth.id",
      createRule: "@request.auth.id != '' && owner = @request.auth.id",
      updateRule: "@request.auth.id != '' && owner = @request.auth.id",
      deleteRule: "@request.auth.id != '' && owner = @request.auth.id",
      indexes: [
        'CREATE UNIQUE INDEX idx_ghost_notif_prefs_owner ON ghost_notification_preferences (owner)',
      ],
      fields: [
        { name: 'owner', type: 'relation', collectionId: users.id, required: true, maxSelect: 1, cascadeDelete: true },
        // Email channel preferences. Security events are never fully
        // suppressible — the hook sends them regardless of the flag, which
        // exists only for transparency in the UI.
        { name: 'email_contribution_reviews', type: 'bool' },
        { name: 'email_project_invitations', type: 'bool' },
        { name: 'email_table_talks', type: 'bool' },
        { name: 'email_collaboration_requests', type: 'bool' },
        { name: 'email_security_events', type: 'bool' },
        { name: 'email_moderation_notices', type: 'bool' },
        // In-app channel preferences (all default on).
        { name: 'inapp_mentions', type: 'bool' },
        { name: 'inapp_system', type: 'bool' },
        { name: 'created', type: 'autodate', onCreate: true },
        { name: 'updated', type: 'autodate', onCreate: true, onUpdate: true },
      ],
    });
    app.save(preferences);
  }
}, (app) => {
  // Revert notifications: drop new fields, restore original type values.
  try {
    const notifications = app.findCollectionByNameOrId('ghost_notifications');
    if (notifications.fields.getByName('category')) {
      notifications.fields.removeByName('category');
    }
    if (notifications.fields.getByName('archived')) {
      notifications.fields.removeByName('archived');
    }
    const typeField = notifications.fields.getByName('type');
    if (typeField) {
      typeField.values = [
        'welcome', 'work_published', 'work_rejected', 'participation_received',
        'application_accepted', 'application_declined', 'report_received',
      ];
    }
    app.save(notifications);
  } catch (_) { /* already absent */ }

  try { app.delete(app.findCollectionByNameOrId('ghost_notification_preferences')); } catch (_) { /* already absent */ }
});
